#include <Arduino.h>
#include <Servo.h>
Servo servo1;
Servo servo2;
Servo servo3;
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
const byte segmentCodes[] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000  
};
int currentNumber = 0;

void setup();
void loop();
void displayNumber(int number);
void moveServos(int number);
void setup() {
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  servo1.attach(2);  
  servo2.attach(3);  
  servo3.attach(4);  
  servo1.write(0);
  servo2.write(0);
  servo3.write(0);
  displayNumber(currentNumber);
}
void loop() {
  for (int i = 0; i <= 9; i++) {
    currentNumber = i;
    displayNumber(currentNumber);
    moveServos(currentNumber);
    delay(2000);  
  }
}
void displayNumber(int number) {
  byte code = segmentCodes[number];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, code);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
void moveServos(int number) {
  if (number >= 0 && number <= 2) {
    servo1.write(0); 
    servo2.write(45);
    servo3.write(90);
  } else if (number >= 3 && number <= 5) {
    servo1.write(45);
    servo2.write(90);
    servo3.write(135);
  } else if (number >= 6 && number <= 8) {
    servo1.write(90);
    servo2.write(135);
    servo3.write(180);
  } else if (number == 9) {
    servo1.write(0);
    servo2.write(0);
    servo3.write(0);
  }
}
